func (q *Queries) ListYieldRules(ctx context.Context, arg ListYieldRulesParams) ([]YieldRule, error) {
	rows, err := q.db.Query(ctx, listYieldRules, arg.TenantID, arg.PropertyID, arg.Active)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []YieldRule{}
	for rows.Next() {
		var i YieldRule
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.PropertyID,
			&i.Code,
			&i.Name,
			&i.RatePlanID,
			&i.RoomTypeID,
			&i.StayFrom,
			&i.StayTo,
			&i.Weekdays,
			&i.OccupancyFrom,
			&i.OccupancyTo,
			&i.LeadMin,
			&i.LeadMax,
			&i.StayMin,
			&i.StayMax,
			&i.AdjustmentType,
			&i.AdjustmentValue,
			&i.FloorAmount,
			&i.CapAmount,
			&i.Priority,
			&i.IsActive,
			&i.CreatedAt,
			&i.CreatedBy,
			&i.UpdatedAt,
			&i.UpdatedBy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

