const upsertRates = `-- name: UpsertRates :one
WITH written AS (
    INSERT INTO rates (tenant_id, property_id, rate_plan_id, room_type_id, stay_date, amount, updated_by)
    SELECT $1::bigint, $2::bigint, $3::bigint, t.room_type_id, d.stay_date::date, $4::numeric, $5::bigint
    FROM unnest($6::bigint[]) AS t (room_type_id)
    CROSS JOIN unnest($7::text[]) AS d (stay_date)
    ON CONFLICT (rate_plan_id, room_type_id, stay_date) DO UPDATE SET amount = EXCLUDED.amount, updated_by = EXCLUDED.updated_by
    RETURNING (xmax = 0) AS inserted
)
SELECT count(*)::bigint AS written, (count(*) FILTER (WHERE inserted))::bigint AS created FROM written
`

type UpsertRatesParams struct {
	TenantID    int64
	PropertyID  int64
	RatePlanID  int64
	Amount      decimal.Decimal
	ActorID     *int64
	RoomTypeIds []int64
	Dates       []string
}

type UpsertRatesRow struct {
	Written int64
	Created int64
}

// Bulk upsert of every (room type, date) pair. Dates arrive as ISO strings (already filtered by weekday).
// Returns how many nights were written and how many of them are new.
func (q *Queries) UpsertRates(ctx context.Context, arg UpsertRatesParams) (UpsertRatesRow, error) {
	row := q.db.QueryRow(ctx, upsertRates,
		arg.TenantID,
		arg.PropertyID,
		arg.RatePlanID,
		arg.Amount,
		arg.ActorID,
		arg.RoomTypeIds,
		arg.Dates,
	)
	var i UpsertRatesRow
	err := row.Scan(&i.Written, &i.Created)
	return i, err
}
